<script>
  import { onMount, tick } from 'svelte';
  import WindowControls from './WindowControls.svelte';
  import { homeWindow, homeCapabilities, homeStatus, homeAutomationTypes } from './home-state.js';
  import { homeMenus } from './home-menus.js';
  import './home.css';
  let { state: homeState, profile, windowId, execute, registerView, available = true, active = true, controls = {} } = $props();
  let root = $state(null), content = $state(null), message = $state(''), dragId = $state(null);
  let originalState, originalProfile, originalId, retired = false, facade;
  const session = $derived(homeWindow(homeState, windowId));
  const capability = $derived(homeCapabilities(profile));
  const currentUser = $derived(homeState.users.find(u => u.id === homeState.currentUserId));
  const editing = $derived(!!(currentUser?.owner || currentUser?.edit));
  const room = $derived(homeState.rooms.find(r => r.id === session?.roomId));
  const selected = $derived(homeState.accessories.find(a => a.id === session?.selectedId));
  const sceneDraft = $derived(session?.sceneDraft);
  const automationDraft = $derived(session?.automationDraft);
  const menus = $derived(homeMenus(homeState, profile, windowId));
  const visible = $derived(homeState.accessories.filter(a => session?.section === 'rooms' ? a.roomId === room?.id : capability.classic ? a.favorite : true));
  const scenes = $derived(homeState.scenes.filter(s => session?.section !== 'home' || !capability.classic || s.favorite));
  const typeLabels = { arrive: 'People Arrive', leave: 'People Leave', time: 'A Time of Day Occurs', accessory: 'An Accessory is Controlled', sensor: 'A Sensor Detects Something' };
  const icons = { light: '☼', thermostat: '♨', lock: '▣', camera: '▰', sensor: '◉' };
  function current() { return !retired && root?.isConnected && homeState === originalState && profile === originalProfile && windowId === originalId; }
  async function command(name, payload = {}) {
    if (!current() || !available || !active) return;
    const owner = root, result = await execute(`home.${name}`, { windowId }, payload);
    if (current() && root === owner) message = result?.status === 'applied' ? result.delivery === 'local-only-not-sent' ? 'Local invitation updated. Nothing was sent to iCloud or another person.' : result.automationResult && result.automationResult !== 'applied' ? `Automation: ${result.automationResult}` : '' : result?.error?.message ?? 'The local Home operation is unavailable.';
    return result;
  }
  function deviceSetting(row, key, value) { command('accessory.settings', { accessoryId: row.id, name: row.name, roomId: row.roomId, favorite: row.favorite, [key]: value }); }
  function values(row, key, value) { command('accessory.set', { accessoryId: row.id, values: { [key]: value } }); }
  function setting(key, value) { command('settings', { name: homeState.name, notes: homeState.notes, wallpaper: homeState.wallpaper, [key]: value }); }
  function toggleAction(kind, device, checked) {
    const draft = kind === 'scene' ? sceneDraft : automationDraft;
    const actions = checked ? [...draft.actions, { accessoryId: device.id, values: { ...device.values } }] : draft.actions.filter(a => a.accessoryId !== device.id);
    command(`${kind}.draft`, { actions });
  }
  function actionValue(kind, deviceId, key, value) { const draft = kind === 'scene' ? sceneDraft : automationDraft; command(`${kind}.draft`, { actions: draft.actions.map(a => a.accessoryId === deviceId ? { ...a, values: { ...a.values, [key]: value } } : { ...a, values: { ...a.values } }) }); }
  function automationType(type) { const source = homeState.accessories.find(a => type === 'sensor' ? a.type === 'sensor' : ['light', 'lock', 'thermostat'].includes(a.type)); command('automation.draft', { type, sourceId: ['accessory', 'sensor'].includes(type) ? source?.id ?? null : null }); }
  function saveRoom(event, roomId) { event.preventDefault(); const form = new FormData(event.currentTarget); command('room.save', { roomId, name: String(form.get('name')), zone: String(form.get('zone')), wallpaper: String(form.get('wallpaper')) }); }
  function invite(event) { event.preventDefault(); const form = new FormData(event.currentTarget); command('invite', { name: String(form.get('name')), email: String(form.get('email')), edit: form.get('edit') === 'on', remote: false, cameras: 'none' }); }
  function key(event) { if (event.key === 'Escape') { event.preventDefault(); command('sheet', { sheet: 'none' }); } }
  onMount(() => {
    originalState = homeState; originalProfile = profile; originalId = windowId;
    facade = {
      available: () => current() && available && active,
      describe: () => ({ appId: 'home', windowId: originalId, native: capability.native, qualified26: capability.qualified26, section: session?.section, sheet: session?.sheet, controlIds: [...(root?.querySelectorAll('[data-home-control]') ?? [])].map(node => node.dataset.homeControl), accessoryIds: visible.map(a => a.id), sceneIds: scenes.map(s => s.id), automationIds: homeState.automations.map(a => a.id), scrolls: { content: { top: content?.scrollTop ?? 0, left: content?.scrollLeft ?? 0 } } }),
      focus: async controlId => { if (!current() || !available || !active) return false; const node = [...root.querySelectorAll('[data-home-control]')].find(n => n.dataset.homeControl === controlId); if (!node || node.disabled || node.closest('[inert]')) return false; node.focus(); await tick(); return current() && root.contains(node) && document.activeElement === node; },
      scroll: async (area, position) => { if (!current() || !available || !active || area !== 'content' || !Number.isFinite(position?.top) || !Number.isFinite(position?.left)) return false; content.scrollTo({ top: Math.max(0, position.top), left: Math.max(0, position.left) }); await tick(); return current(); },
      destroy: () => { retired = true; },
    };
    registerView(windowId, facade);
    return () => { retired = true; registerView(originalId, null, facade); };
  });
</script>

<section bind:this={root} class="home-app" class:classic={capability.classic} class:modern={!capability.classic && capability.native} class:golden={capability.qualified26} class:windows={capability.windows} class:equivalent={!capability.native} class:inactive={!active} data-home-window-id={windowId} data-profile={profile.id} data-wallpaper={session?.section === 'rooms' ? room?.wallpaper : homeState.wallpaper} onkeydown={key} role="region" aria-label={capability.label} tabindex="-1">
  <div class="home-main" inert={!!session?.sheet && session.sheet !== 'none' || !active || !available}>
    <header class="home-titlebar">
      {#if !capability.windows}<WindowControls {active} onclose={() => command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} onsplitbegin={controls.onsplitbegin} onsplitside={controls.onsplitside} ongreenmenu={controls.ongreenmenu} fullScreen={controls.fullScreen} revealedTop={controls.revealedTop} modernGreenMenu={controls.modernGreenMenu} zoomed={controls.zoomed}/>{/if}
      {#if capability.classic}<button class="home-house" aria-label="Home settings" data-home-control="settings" onclick={() => command('sheet', { sheet: 'settings' })}>⌂⌄</button><nav class="home-tabs" aria-label="Home views">{#each [['home','Home'],['rooms','Rooms'],['automation','Automation']] as [id,label]}<button class:selected={session?.section === id} data-home-control={`navigate:${id}`} onclick={() => command('navigate', { section: id })}>{label}</button>{/each}</nav>{:else}<strong>{capability.native ? homeState.name : capability.label}</strong>{/if}
      <button class="home-add" aria-label="Add scene or automation" data-home-control="add" onclick={() => command('menu', { menu: session?.menu === 'file' ? 'none' : 'file' })}>＋</button>
      {#if !capability.classic}<button aria-label="Home settings" data-home-control="settings" onclick={() => command('sheet', { sheet: 'settings' })}>•••</button>{/if}
    </header>
    <nav class="home-menubar" aria-label="Home application menus">{#each menus as menu}<button class:selected={session?.menu === menu.id} data-home-control={`menu:${menu.id}`} onclick={() => command('menu', { menu: session?.menu === menu.id ? 'none' : menu.id })}>{menu.label}</button>{/each}</nav>
    {#if session?.menu && session.menu !== 'none'}<div class="home-menu" role="menu" aria-label={session.menu}>{#each menus.find(m => m.id === session.menu)?.items ?? [] as item}<button role="menuitem" disabled={!item.enabled} data-home-control={`menuitem:${item.id}`} onclick={() => command(item.command.slice(5), item.payload)}>{item.label}</button>{/each}</div>{/if}
    {#if !capability.native || capability.qualified26}<p class="home-disclosure">{capability.disclosure}</p>{/if}
    <div class="home-workspace">
      {#if !capability.classic}<aside class="home-sidebar"><button class:selected={session?.section === 'home'} data-home-control="navigate:home" onclick={() => command('navigate', { section: 'home' })}>⌂ Home</button><button class:selected={session?.section === 'automation'} data-home-control="navigate:automation" onclick={() => command('navigate', { section: 'automation' })}>◉ Automations</button><h3>Rooms</h3>{#each homeState.rooms as r}<button class:selected={session?.section === 'rooms' && room?.id === r.id} data-home-control={`room:${r.id}`} onclick={() => command('navigate', { section: 'rooms', roomId: r.id })}>▢ {r.name}</button>{/each}<button data-home-control="help" onclick={() => command('sheet', { sheet: 'help' })}>Home Help</button></aside>{/if}
      <main bind:this={content} class="home-content" data-home-area="content">
        {#if session?.section === 'automation'}
          <h1>Automation</h1><p>Automatically run scenes with the fictional home hub. Time triggers use the authored scene clock (UTC), not your computer’s clock.</p>
          {#if !homeState.hubAvailable}<p class="home-warning">Home Hub Not Responding — automations cannot run.</p>{/if}
          <button disabled={!editing || !homeState.hubAvailable} data-home-control="automation:add" onclick={() => command('automation.edit', { automationId: null })}>Add Automation…</button>
          <div class="home-automation-list">{#each homeState.automations as automation}<article><button data-home-control={`automation:${automation.id}`} onclick={() => command('automation.edit', { automationId: automation.id })}><strong>{automation.name}</strong><small>{typeLabels[automation.type]} · {automation.lastResult}{automation.type === 'time' ? ` · ${String(Math.floor(automation.minute/60)).padStart(2,'0')}:${String(automation.minute%60).padStart(2,'0')} UTC` : ''}</small></button><label><input type="checkbox" checked={automation.enabled} disabled={!editing} data-home-control={`automation:enabled:${automation.id}`} onchange={e => command('automation.enabled', { automationId: automation.id, enabled: e.currentTarget.checked })}/>Enabled</label><button data-home-control={`automation:test:${automation.id}`} disabled={!editing || !homeState.hubAvailable} onclick={() => command('automation.test', { automationId: automation.id })}>Test This Automation</button></article>{/each}{#if !homeState.automations.length}<p>No Automations. Add a time, arrival, departure, accessory or sensor trigger.</p>{/if}</div>
        {:else}
          {#if session?.section === 'rooms' && capability.classic}<label class="home-room-picker">Room <select data-home-control="room-picker" value={room?.id} onchange={e => command('navigate', { section: 'rooms', roomId: e.currentTarget.value })}>{#each homeState.rooms as r}<option value={r.id}>{r.name}</option>{/each}</select></label>{/if}
          <h1>{session?.section === 'rooms' ? room?.name : homeState.name}</h1>
          <p class="home-summary">{homeState.accessories.filter(a => a.type === 'light' && a.available && a.values.on).length} lights on.<br/>{homeState.accessories.filter(a => a.type === 'lock' && a.available && !a.values.locked).length} doors unlocked.<br/>{homeState.accessories.filter(a => !a.available).length} accessories not responding.</p>
          {#if !capability.classic}
            <div class="home-categories"><span>♨ Climate · {homeState.accessories.find(a => a.type === 'thermostat')?.values.target}°</span><span>☼ Lights · {homeState.accessories.filter(a => a.type === 'light' && a.values.on).length} On</span><span>▣ Security · Local only</span></div>
            <h2>Cameras</h2>
            {#each visible.filter(a => a.type === 'camera') as camera}
              <button class="home-camera-preview" data-home-control={`camera:${camera.id}`} onclick={() => command('accessory.open', { accessoryId: camera.id })}>
                {#if camera.available && currentUser?.cameras !== 'none'}<svg viewBox="0 0 420 140" role="img" aria-label="Authored drawing of a fictional porch, not camera footage"><rect width="420" height="140" fill="#8badbe"/><path d="M0 100 Q140 70 260 102 T420 92 V140H0" fill="#578975"/><path d="M170 85V35H270V115H170" fill="#d7d0b9"/><path d="M150 35L220 4L290 35" fill="#555c62"/><rect x="210" y="64" width="30" height="51" fill="#58646c"/><path d="M220 115L248 140H191Z" fill="#d9cdb4"/></svg>{/if}
                <span>{camera.name} · {!camera.available ? 'No Response' : currentUser?.cameras === 'none' ? 'Preview unavailable for this resident' : 'Authored local preview — no camera'}</span>
              </button>
            {/each}
          {/if}
          <h2>{capability.classic ? 'Favorite Scenes' : 'Scenes'}</h2><div class="home-scene-grid">{#each scenes as scene}<article><button class="home-scene" data-home-control={`scene:${scene.id}`} onclick={() => command('scene.run', { sceneId: scene.id })}>⌂ <strong>{scene.name}</strong></button><button aria-label={`Edit ${scene.name}`} disabled={!editing} data-home-control={`scene:edit:${scene.id}`} onclick={() => command('scene.edit', { sceneId: scene.id })}>•••</button></article>{/each}</div>
          {#each capability.classic || session?.section === 'rooms' ? [{ id: session?.section === 'rooms' ? room?.id : null, name: session?.section === 'rooms' ? 'Accessories' : 'Favorite Accessories' }] : homeState.rooms as group}
            <h2>{group.name}</h2>
            <div class="home-accessory-grid">
              {#each visible.filter(a => group.id === null || a.roomId === group.id) as device}
                <article draggable={editing} ondragstart={e => { dragId = device.id; e.dataTransfer.effectAllowed = 'move'; }} ondragover={e => { if (dragId) e.preventDefault(); }} ondrop={e => { e.preventDefault(); if (dragId) command('accessory.reorder', { accessoryId: dragId, beforeId: device.id }); dragId = null; }} ondragend={() => dragId = null}>
                  <button class="home-tile" class:on={device.available && (device.type === 'light' ? device.values.on : device.type === 'lock' ? !device.values.locked : true)} class:unavailable={!device.available} data-home-control={`accessory:${device.id}`} onclick={() => ['camera','sensor'].includes(device.type) ? command('accessory.open', { accessoryId: device.id }) : command('accessory.toggle', { accessoryId: device.id })} ondblclick={() => command('accessory.open', { accessoryId: device.id })} oncontextmenu={e => { e.preventDefault(); command('accessory.open', { accessoryId: device.id }); }}>
                    <span class="home-device-icon">{icons[device.type]}</span><small>{homeState.rooms.find(r => r.id === device.roomId)?.name}</small><strong>{device.name}</strong><span>{homeStatus(device)}</span>
                  </button>
                  <button class="home-tile-detail" aria-label={`Show controls for ${device.name}`} data-home-control={`accessory:details:${device.id}`} onclick={() => command('accessory.open', { accessoryId: device.id })}>•••</button>
                </article>
              {/each}
            </div>
          {/each}
        {/if}
      </main>
    </div>
    <footer class="home-status" role="status">{message || 'Authored local fiction · no real IoT access'}</footer>
  </div>
  {#if session?.sheet && session.sheet !== 'none'}<div class="home-sheet-backdrop"><section class="home-sheet" role="dialog" aria-modal="true" aria-label={session.sheet}>
    <header><h2>{session.sheet === 'accessory' ? selected?.name : session.sheet === 'scene' ? 'Scene Settings' : session.sheet === 'automation' ? 'Automation' : session.sheet === 'room' ? 'Room Settings' : session.sheet === 'settings' ? 'Home Settings' : session.sheet === 'about' ? 'About Home' : 'Home Help'}</h2><button data-home-control="sheet:done" onclick={() => command('sheet', { sheet: 'none' })}>Done</button></header>
    {#if session.sheet === 'accessory' && selected}
      <p>{homeStatus(selected)}</p>
      {#if !selected.available}<p class="home-warning">No Response. This fictional device is unavailable. Controls cannot change its state.</p>{/if}
      {#if selected.type === 'light'}<label><input type="checkbox" checked={selected.values.on} disabled={!selected.available} data-home-control="device:on" onchange={e => values(selected, 'on', e.currentTarget.checked)}/>Power</label><label>Brightness {selected.values.brightness}% <input type="range" min="0" max="100" value={selected.values.brightness} disabled={!selected.available} data-home-control="device:brightness" onchange={e => values(selected, 'brightness', Number(e.currentTarget.value))}/></label><label>Color<select value={selected.values.color} disabled={!selected.available} data-home-control="device:color" onchange={e => values(selected, 'color', e.currentTarget.value)}>{#each ['warm','white','blue','red'] as color}<option>{color}</option>{/each}</select></label>
      {:else if selected.type === 'thermostat'}<div class="home-thermostat">{selected.values.target}°</div><label>Target Temperature (°C)<input type="range" min="10" max="32" value={selected.values.target} disabled={!selected.available} data-home-control="device:temperature" onchange={e => values(selected, 'target', Number(e.currentTarget.value))}/></label><label>Mode<select value={selected.values.mode} disabled={!selected.available} data-home-control="device:mode" onchange={e => values(selected, 'mode', e.currentTarget.value)}>{#each ['off','heat','cool','auto'] as mode}<option>{mode}</option>{/each}</select></label>
      {:else if selected.type === 'lock'}<button disabled={!selected.available} class="home-lock-control" data-home-control="device:lock" onclick={() => values(selected, 'locked', !selected.values.locked)}>{selected.values.locked ? '▣ Locked — Unlock' : '▢ Unlocked — Lock'}</button><p>Explicit local control only; no real door is affected.</p>
      {:else if selected.type === 'camera'}{#if currentUser?.cameras !== 'none' && selected.available}<div class="home-camera-detail"><svg viewBox="0 0 420 180" role="img" aria-label="Fictional porch illustration"><rect width="420" height="180" fill="#8badbe"/><path d="M0 130Q200 70 420 120V180H0" fill="#578975"/><path d="M150 120V45H280V140H150" fill="#d7d0b9"/><path d="M130 45L215 5L300 45" fill="#555c62"/><rect x="200" y="80" width="35" height="60" fill="#58646c"/></svg><strong>AUTHORED LOCAL PREVIEW</strong></div>{:else}<p>Camera preview unavailable for this resident or device.</p>{/if}<p>No stream, microphone, recording, cloud storage or camera is accessed.</p>
      {:else}<p>Fictional sensor: {selected.values.motion ? 'Motion detected' : 'No motion'}</p><button data-home-control="sensor:trigger" disabled={!selected.available} onclick={() => command('local.sensor', { accessoryId: selected.id, motion: !selected.values.motion })}>Simulate {selected.values.motion ? 'No Motion' : 'Motion'} Locally</button>{/if}
      <hr/><h3>Settings</h3><label>Name<input value={selected.name} maxlength="160" disabled={!editing} data-home-control="device:name" onchange={e => deviceSetting(selected, 'name', e.currentTarget.value)}/></label><label>Room<select value={selected.roomId} disabled={!editing} data-home-control="device:room" onchange={e => deviceSetting(selected, 'roomId', e.currentTarget.value)}>{#each homeState.rooms as r}<option value={r.id}>{r.name}</option>{/each}</select></label><label><input type="checkbox" checked={selected.favorite} disabled={!editing} data-home-control="device:favorite" onchange={e => deviceSetting(selected, 'favorite', e.currentTarget.checked)}/>Include in Favorites</label>{#if currentUser?.owner}<button data-home-control="device:availability" onclick={() => command('local.device', { accessoryId: selected.id, available: !selected.available })}>Local fixture: mark {selected.available ? 'unavailable' : 'available'}</button>{/if}
    {:else if session.sheet === 'scene' && sceneDraft}
      <label>Name<input value={sceneDraft.name} maxlength="160" data-home-control="scene:name" onchange={e => command('scene.draft', { name: e.currentTarget.value })}/></label><label><input type="checkbox" checked={sceneDraft.favorite} data-home-control="scene:favorite" onchange={e => command('scene.draft', { favorite: e.currentTarget.checked })}/>Include in Favorites</label>
      <h3>Add or Remove Accessories</h3>{#each homeState.accessories.filter(a => !['camera','sensor'].includes(a.type)) as device}{@const action = sceneDraft.actions.find(a => a.accessoryId === device.id)}<div class="home-action-editor"><label><input type="checkbox" checked={!!action} data-home-control={`scene:include:${device.id}`} onchange={e => toggleAction('scene', device, e.currentTarget.checked)}/>{device.name}{!device.available ? ' — No Response' : ''}</label>{#if action}{#if device.type === 'light'}<label>Power<input type="checkbox" checked={action.values.on} data-home-control={`scene:on:${device.id}`} onchange={e => actionValue('scene', device.id, 'on', e.currentTarget.checked)}/></label><label>Brightness<input type="range" min="0" max="100" value={action.values.brightness} data-home-control={`scene:brightness:${device.id}`} onchange={e => actionValue('scene', device.id, 'brightness', Number(e.currentTarget.value))}/></label><label>Color<select value={action.values.color} data-home-control={`scene:color:${device.id}`} onchange={e => actionValue('scene', device.id, 'color', e.currentTarget.value)}>{#each ['warm','white','blue','red'] as color}<option>{color}</option>{/each}</select></label>{:else if device.type === 'lock'}<label>Locked<input type="checkbox" checked={action.values.locked} data-home-control={`scene:locked:${device.id}`} onchange={e => actionValue('scene', device.id, 'locked', e.currentTarget.checked)}/></label>{:else}<label>Temperature<input type="number" min="10" max="32" value={action.values.target} data-home-control={`scene:temperature:${device.id}`} onchange={e => actionValue('scene', device.id, 'target', Number(e.currentTarget.value))}/></label><label>Mode<select value={action.values.mode} data-home-control={`scene:mode:${device.id}`} onchange={e => actionValue('scene', device.id, 'mode', e.currentTarget.value)}>{#each ['off','heat','cool','auto'] as mode}<option>{mode}</option>{/each}</select></label>{/if}{/if}</div>{/each}
      <button class="home-primary" data-home-control="scene:save" onclick={() => command('scene.save')}>Save Scene</button>{#if sceneDraft.id}<button class="home-danger" data-home-control="scene:delete" onclick={() => command('scene.delete', { sceneId: sceneDraft.id, confirm: true })}>Delete Scene</button>{/if}<p>Done discards unsaved editor changes. Other windows’ saved edits require reopening this editor.</p>
    {:else if session.sheet === 'automation' && automationDraft}
      <label>Name<input value={automationDraft.name} maxlength="160" data-home-control="automation:name" onchange={e => command('automation.draft', { name: e.currentTarget.value })}/></label><label><input type="checkbox" checked={automationDraft.enabled} data-home-control="automation:enabled" onchange={e => command('automation.draft', { enabled: e.currentTarget.checked })}/>Enable This Automation</label>
      <label>When<select value={automationDraft.type} data-home-control="automation:type" onchange={e => automationType(e.currentTarget.value)}>{#each homeAutomationTypes as type}<option value={type}>{typeLabels[type]}</option>{/each}</select></label>
      {#if automationDraft.type === 'time'}<label>Time of Day (authored UTC)<input type="time" value={`${String(Math.floor(automationDraft.minute/60)).padStart(2,'0')}:${String(automationDraft.minute%60).padStart(2,'0')}`} data-home-control="automation:time" onchange={e => { const [hour,minute] = e.currentTarget.value.split(':').map(Number); command('automation.draft', { minute: hour*60+minute }); }}/></label><fieldset><legend>Repeat</legend>{#each ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'] as day, index}<label><input type="checkbox" checked={automationDraft.days.includes(index)} data-home-control={`automation:day:${index}`} onchange={e => command('automation.draft', { days: e.currentTarget.checked ? [...automationDraft.days,index] : automationDraft.days.filter(d => d !== index) })}/>{day}</label>{/each}</fieldset>{:else if ['accessory','sensor'].includes(automationDraft.type)}<label>Source<select value={automationDraft.sourceId} data-home-control="automation:source" onchange={e => command('automation.draft', { sourceId: e.currentTarget.value })}>{#each homeState.accessories.filter(a => automationDraft.type === 'sensor' ? a.type === 'sensor' : ['light','lock','thermostat'].includes(a.type)) as a}<option value={a.id}>{a.name}</option>{/each}</select></label><label>Detect<select value={String(automationDraft.trigger)} data-home-control="automation:trigger" onchange={e => command('automation.draft', { trigger: e.currentTarget.value === 'true' })}><option value="true">{automationDraft.type === 'sensor' ? 'Motion' : 'On / Locked / Heating'}</option><option value="false">{automationDraft.type === 'sensor' ? 'No Motion' : 'Off / Unlocked / Idle'}</option></select></label>{:else}<p>Arrival and departure are explicit local fixture events, not real location tracking. Your Mac cannot supply native location-based automation.</p>{/if}
      <label>People<select value={automationDraft.presence} data-home-control="automation:presence" onchange={e => command('automation.draft', { presence: e.currentTarget.value })}><option value="any">Anybody</option><option value="home">When somebody is home</option><option value="away">When nobody is home</option></select></label>
      <h3>Scenes</h3>{#each homeState.scenes as s}<label><input type="checkbox" checked={automationDraft.sceneIds.includes(s.id)} data-home-control={`automation:scene:${s.id}`} onchange={e => command('automation.draft', { sceneIds: e.currentTarget.checked ? [...automationDraft.sceneIds,s.id] : automationDraft.sceneIds.filter(id => id !== s.id) })}/>{s.name}</label>{/each}
      <h3>Accessories</h3>{#each homeState.accessories.filter(a => !['camera','sensor'].includes(a.type)) as device}{@const action = automationDraft.actions.find(a => a.accessoryId === device.id)}<div class="home-action-editor"><label><input type="checkbox" checked={!!action} data-home-control={`automation:include:${device.id}`} onchange={e => toggleAction('automation', device, e.currentTarget.checked)}/>{device.name}</label>{#if action}{#if device.type === 'light'}<label>Power<input type="checkbox" checked={action.values.on} data-home-control={`automation:on:${device.id}`} onchange={e => actionValue('automation', device.id, 'on', e.currentTarget.checked)}/></label><label>Brightness<input type="range" min="0" max="100" value={action.values.brightness} data-home-control={`automation:brightness:${device.id}`} onchange={e => actionValue('automation', device.id, 'brightness', Number(e.currentTarget.value))}/></label>{:else if device.type === 'lock'}<label>Locked<input type="checkbox" checked={action.values.locked} data-home-control={`automation:locked:${device.id}`} onchange={e => actionValue('automation', device.id, 'locked', e.currentTarget.checked)}/></label>{:else}<label>Target °C<input type="number" min="10" max="32" value={action.values.target} data-home-control={`automation:temperature:${device.id}`} onchange={e => actionValue('automation', device.id, 'target', Number(e.currentTarget.value))}/></label><label>Mode<select value={action.values.mode} data-home-control={`automation:mode:${device.id}`} onchange={e => actionValue('automation', device.id, 'mode', e.currentTarget.value)}>{#each ['off','heat','cool','auto'] as mode}<option>{mode}</option>{/each}</select></label>{/if}{/if}</div>{/each}
      <label>Turn Off Lights After (minutes; 0 = never)<input type="number" min="0" max="240" value={automationDraft.turnOffMinutes} data-home-control="automation:turn-off" onchange={e => command('automation.draft', { turnOffMinutes: Number(e.currentTarget.value) })}/></label><p>No recursive automation cascades. Unattended door unlocking requires confirmation and does not run. A large scene-clock jump runs at most the latest matching occurrence.</p><button class="home-primary" disabled={!homeState.hubAvailable} data-home-control="automation:save" onclick={() => command('automation.save')}>Done — Save Automation</button>{#if automationDraft.id}<button class="home-danger" data-home-control="automation:delete" onclick={() => command('automation.delete', { automationId: automationDraft.id, confirm: true })}>Delete Automation</button>{/if}
    {:else if session.sheet === 'room' && room}
      <form onsubmit={e => saveRoom(e, room.id)}><label>Name<input name="name" value={room.name} required maxlength="160" data-home-control="room:name"/></label><label>Zone<input name="zone" value={room.zone} maxlength="160" data-home-control="room:zone"/></label><label>Wallpaper<select name="wallpaper" value={room.wallpaper} data-home-control="room:wallpaper">{#each ['blue','orange','green'] as color}<option>{color}</option>{/each}</select></label><button disabled={!editing} data-home-control="room:save">Save Room</button></form><button class="home-danger" disabled={!editing || homeState.rooms.length === 1} data-home-control="room:delete" onclick={() => command('room.delete', { roomId: room.id, confirm: true })}>Remove Room — move accessories to another room</button><h3>Create New Room</h3><form onsubmit={e => saveRoom(e, null)}><label>Name<input name="name" required maxlength="160" data-home-control="room:new-name"/></label><label>Zone<input name="zone" maxlength="160" data-home-control="room:new-zone"/></label><input type="hidden" name="wallpaper" value="blue"/><button disabled={!editing} data-home-control="room:add">Add Room</button></form>
    {:else if session.sheet === 'settings'}
      <label>Name<input value={homeState.name} disabled={!editing} maxlength="160" data-home-control="settings:name" onchange={e => setting('name', e.currentTarget.value)}/></label><label>Home Notes<textarea value={homeState.notes} disabled={!editing} maxlength="8192" data-home-control="settings:notes" onchange={e => setting('notes', e.currentTarget.value)}></textarea></label><label>Home Wallpaper<select value={homeState.wallpaper} disabled={!editing} data-home-control="settings:wallpaper" onchange={e => setting('wallpaper', e.currentTarget.value)}>{#each ['blue','orange','green'] as color}<option>{color}</option>{/each}</select></label>
      <h3>People</h3>{#each homeState.users as person}<article class="home-person"><strong>{person.name}{person.owner ? ' (Owner)' : ''}</strong><small>{person.email}</small><label><input type="checkbox" checked={person.edit} disabled={!currentUser?.owner || person.owner} data-home-control={`user:edit:${person.id}`} onchange={e => command('user.set', { userId: person.id, values: { edit: e.currentTarget.checked } })}/>Add and Edit Accessories</label><label><input type="checkbox" checked={person.remote} disabled={!currentUser?.owner || person.owner} data-home-control={`user:remote:${person.id}`} onchange={e => command('user.set', { userId: person.id, values: { remote: e.currentTarget.checked } })}/>Allow Remote Access (fictional permission only)</label>{#if !capability.classic && capability.native}<label>Cameras<select value={person.cameras} disabled={!currentUser?.owner} data-home-control={`user:cameras:${person.id}`} onchange={e => command('user.set', { userId: person.id, values: { cameras: e.currentTarget.value } })}><option value="none">Off</option><option value="stream">Stream</option><option value="recordings">Stream & View Recordings (no recordings in this fiction)</option></select></label>{/if}{#if !person.owner}<button disabled={!currentUser?.owner || person.id === homeState.currentUserId} data-home-control={`user:remove:${person.id}`} onclick={() => command('user.remove', { userId: person.id, confirm: true })}>Remove Person</button>{/if}</article>{/each}
      <h3>Invite People</h3><p>Local invitations only. No Apple account lookup, email or iCloud invite is sent. Native invitations require iCloud; this authored scene has no service connection.</p><form onsubmit={invite}><label>Name<input name="name" required maxlength="160" data-home-control="invite:name"/></label><label>Fictional email<input name="email" type="email" required maxlength="320" data-home-control="invite:email"/></label><label><input name="edit" type="checkbox" data-home-control="invite:edit"/>Allow editing</label><button disabled={!currentUser?.owner} data-home-control="invite:send">Create Local Invite</button></form>{#each homeState.invitations as invitation}<article class="home-person"><strong>{invitation.name}</strong><small>{invitation.email} · Invitation Pending (local only)</small><button disabled={!currentUser?.owner} data-home-control={`invite:accept:${invitation.id}`} onclick={() => command('local.invitation.accept', { invitationId: invitation.id })}>Simulate Acceptance Locally</button><button disabled={!currentUser?.owner} data-home-control={`invite:cancel:${invitation.id}`} onclick={() => command('invite.cancel', { invitationId: invitation.id })}>Cancel Invite</button></article>{/each}
      <h3>Local Fiction Controls — not native service controls</h3><label>Act as local resident<select value={homeState.currentUserId} data-home-control="local:user" onchange={e => command('local.user', { userId: e.currentTarget.value })}>{#each homeState.users as person}<option value={person.id}>{person.name}</option>{/each}</select></label><label><input type="checkbox" checked={homeState.hubAvailable} disabled={!currentUser?.owner} data-home-control="local:hub" onchange={e => command('local.hub', { available: e.currentTarget.checked })}/>Fictional home hub available</label><button data-home-control="local:presence" onclick={() => command('local.presence', { home: !homeState.peopleHome })}>Simulate {homeState.peopleHome ? 'People Leave' : 'People Arrive'} Locally</button><p>People are currently {homeState.peopleHome ? 'home' : 'away'}. Mac location is never queried.</p><button disabled={!editing} data-home-control="settings:rooms" onclick={() => command('sheet', { sheet: 'room' })}>Edit Rooms…</button>
    {:else}
      <h3>{capability.label}</h3><p>{capability.disclosure}</p><p>Click an accessory to control it. Double-click, right-click or choose its detail button for controls and Settings. Include accessories in Favorites, rename them or move them between rooms. Drag tiles to reorder them.</p><p>Add Scene groups local accessory settings. Editors are canonical per-window drafts; Save commits, Done cancels. Add Automation offers people arriving/leaving, a time of day, an accessory being controlled and sensor detection. Automations require the local hub. UTC scene-time changes, not wall-clock timers, trigger scheduled actions.</p><p>Home Settings holds the fictional owner, residents and local invitations. Residents without Add and Edit permission can control available devices but cannot modify the home. Camera previews are clearly authored illustrations. No pairing, network discovery, iCloud authentication, IoT request, location, purchase or recording occurs.</p>{#if capability.classic}<p>Mojave uses Home, Rooms and Automation tabs. Scenes and automations can be created on Mac; adding a new physical accessory requires iOS, so pairing is not offered. Later camera recording permissions and Matter are not backported.</p>{/if}
    {/if}
    {#if message}<p role="alert" class="home-warning">{message}</p>{/if}
  </section></div>{/if}
</section>
